-- Akshat Fertilizers product catalogue, transcribed from https://www.akshatfertilizer.com (56 products).
-- Products load HIDDEN with no price: set price / GST / pack / stock in Admin → Products & Pricing, then switch them on.
-- Safe to re-run: refreshes website content only; never touches price, GST, HSN, pack, unit or on/off status.
-- HSN / GST below are starting defaults per category — verify each before activating.

insert into public.products (sku, name, category, subcategory, description, specs, image_url, brochure_url, source_url, hsn_code, gst_rate, unit, sort_order, is_active, price)
select v.*, false, null::numeric from (values
  ('AF-1-6-1', 'Seerin-19:19:19', 'Green House Grade Fertilizers', 'NPK grade Fertilizers', 'Seerin-NPK (19:19:19) is a fully Water Soluble Fertilizer, a high efficient source of Nitrogen, Phosphorus, and Potassium for plants., Seerin-multiN, NPK (19:19:19) is the proffered source of NPK in proportion of 1:1:1 as Nitrogen ,Phosphorus and Potash- 19:19:19 at the productive stage of crops (vegetables & fruit) helps to increase sugar content and to improve the quality of these. its high purity and water solubility makes different to other. Seerin- N.P.K(19:19:19) an ideal fertilizer for fertigation at harvesting stages of all vegetable crops.', '[["Specification","Grade"],["Total Nitrogen Minimum","19.00"],["Nitrate Nitrogen Maximum","4.00"],["Ammonical Nitrogen Minimum","4.50"],["Urea Nitrogen Maximum","10.50"],["Water Soluble Phosphate as P2O5 Minimum","19.00"],["Water Soluble Potash as K2O Minimum","19.00"],["Sodium as NaCl on dry basis Maximum","0.50"],["Moisture Maximum","0.50"]]'::jsonb, 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/1580710420191919.png', 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/164404399491919-New.pdf', 'https://www.akshatfertilizer.com/products-view.php?category=1&products=6&productsId=1', '3105', 5, 'BAG', 10),
  ('AF-1-6-2', 'Seerin-13:40:13', 'Green House Grade Fertilizers', 'NPK grade Fertilizers', 'Seerin-13:40:13 is a 100% water soluble fertilizer and chloride free,This nitrogen ,phosphorus and potash proportionate for mutation is beneficial to all crops during pre and post flowering stage.', '[["Specification","Grade"],["Total Nitrogen Minimum","13.0"],["Nitrate Nitrogen Maximum","4.4"],["Ammonical Nitrogen Minimum","8.6"],["Water Soluble Phosphates as P2O5 Minimum","40.0"],["Water Soluble Potash as K2O Minimum","13.0"],["Sodium as Nacl on dry basis Maximum","0.15"],["Matter insoluble in water Maximum","0.5"],["Moisture % by weight Maximum","0.5"]]'::jsonb, 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/1580710489134013.png', 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/164404401734013-New.pdf', 'https://www.akshatfertilizer.com/products-view.php?category=1&products=6&productsId=2', '3105', 5, 'BAG', 20),
  ('AF-1-6-3', 'Seerin-16:08:24', 'Green House Grade Fertilizers', 'NPK grade Fertilizers', 'Seerin-NPK (16: 08 : 24) is a fully water soluble fertilizer, a high efficient source of Nitrogen, Phosphorus, and Potassium for plants. It is chloride free fertilizer, Seerin-multi-N, N.P.K is the preferred source of NPK in proportion of 2:1:3 as Nitrogen, phosphorus and potash- 16:08:24 at the productive stage of crops(vegetables & fruit) helps to increase sugar content and to improve the quality of these. its high purity and water solubility makes different to other', '[["Specification","Grade"],["Total Nitrogen % by weight , Minimum","16.00"],["Nitrate Nitrogen Maximum","4.00"],["Ammonical Nitrogen % weight , Maximum","4.05"],["Urea Nitrogen % by weight, Maximum","7.50"],["Water Soluble Phosphate as P2O5 % by weight","8.00"],["Water Soluble Potash as K2O % by weight, minimum","24.00"],["Matter insoluble in water % by weight, Maximum","0.50"],["Moisture % by weight, Maximum","0.50"]]'::jsonb, 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/1580710542160824.png', 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/164404405960824-New.pdf', 'https://www.akshatfertilizer.com/products-view.php?category=1&products=6&productsId=3', '3105', 5, 'BAG', 30),
  ('AF-1-6-4', 'Seerin-17:09:29', 'Green House Grade Fertilizers', 'NPK grade Fertilizers', 'Seerin-NPK (17:09:29) is a fully water soluble fertilizer, a high efficient source of Nitrogen, Phosphorus, and Potassium for plants. It is chloride free fertilizer, Seerin-multi-N,(17:09:29) is the preferred source of NPK in proportion of 2:1:3 as Nitrogen, phosphorus and potash', '[["Specification","Grade"],["Total Nitrogen % by weight","17.00"],["Nitrate Nitrogen as N% by weight , Maximum","8.30"],["Ammonical Nitrogen % by weight, Minimum","4.30"],["Urea Nitrogen % by weight, Maximum","4.40"],["Water Soluble Phosphate as P2O5 % by weight","9.00"],["water Soluble Potash as K2O % by weight, Minimum","29.00"],["Matter Insoluble in water % by weight, Maximum","0.50"],["Moisture % by weight, Maximum","0.50"]]'::jsonb, 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/1580710605WhatsApp_Image_2019-12-20_at_12-removebg-preview-(17).png', 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/164404420370929-New-pdf.pdf', 'https://www.akshatfertilizer.com/products-view.php?category=1&products=6&productsId=4', '3105', 5, 'BAG', 40),
  ('AF-1-6-5', 'Seerin-30:10:10', 'Green House Grade Fertilizers', 'NPK grade Fertilizers', 'seerin- N.P.K (30:10:10) is an main supplement to soil fertilization at growth stage when high levels of phosphorus and potassium and nitrogen are required. the three most important nutrients, without any one of which plants could not survive, are referred to as the primary macronutrients: Nitrogen (N), Phosphorus (P), and Potassium (K).', '[["Specification","Grade"],["Moisture % Maximum","1.5"],["Total Nitrogen % Maximum","30.0"],["Total water soluble phosphate %","10.0"],["Total water soluble Potash %","10.0"],["Boron as (B) % by weight ,Minimum","0.5"],["Sulphur as (S) % , Minimum","3.0"],["Matter Insoluble in water %","0.5"],["Sodium as NaCl % ,Maximum","0.5"],["Total Chloride, % Maximum","0.5"],["Lead as (pb) ,% Maximum","0.003"],["Cadmium as (Cd), % Maximum","0.0025"],["Arsenic as ( As),% Maximum","0.01"],["Additional trace elements","1.0"]]'::jsonb, 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/1580710645301010.png', 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/164404423501010-New.pdf', 'https://www.akshatfertilizer.com/products-view.php?category=1&products=6&productsId=5', '3105', 5, 'BAG', 50),
  ('AF-1-7-6', 'Seerin-12:61:00', 'Green House Grade Fertilizers', 'Phosphate Grade Fertilizers', 'Seerin- MAP™ is a fully water-soluble fertilizer for fertigation™ and foliar feeding of all crops As a highly efficient source of phosphorus and nitrogen for plants, Seerin-MAP™ is recommended for use at the beginning of the growth season, when phosphorus availability is crucial for the establishment of the root system.', '[["Specification","Grade"],["moisture Maximum","0.50"],["Ammonical Nitrogen Minimum","12.00"],["Water Soluble Phosphate as P2O5, Minimum","61.00"],["Sodium as NaCl Maximum","0.50"],["Matter Insoluble in water Maximum","0.50"]]'::jsonb, 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/1580710678126100.png', 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/164404428026100-New.pdf', 'https://www.akshatfertilizer.com/products-view.php?category=1&products=7&productsId=6', '3105', 5, 'BAG', 60),
  ('AF-1-7-7', 'Seerin-00:52:34', 'Green House Grade Fertilizers', 'Phosphate Grade Fertilizers', 'Seerin- PHOSPHA-TM (00:52:34) is a fully water-soluble Mono-Potassium Phosphate fertilizer, a highly efficient source of phosphorus and potassium for plants. As a nitrogen-free fertilizer, A common case is at early growing season, when phosphorus and potassium are needed at high rates for the establishment of rootsystem..Its high purity and water-solubility make Seerin- MKP (00:52:34) an ideal fertilizer for fertization and for foliar application', '[["Specification","grade"],["Water soluble phosphate as P2O5 % by weight , Minimum","52.00"],["Water soluble Potash as K2O % by weight , Minimum","34.00"],["Sodium as NaCl by weight on dry basis, Maximum","0.025"],["Moisture by weight, Maximum","0.50"]]'::jsonb, 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/1580710725005234.png', 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/164404430605234-New.pdf', 'https://www.akshatfertilizer.com/products-view.php?category=1&products=7&productsId=7', '3105', 5, 'BAG', 70),
  ('AF-1-7-8', 'Seerin-00:60:20', 'Green House Grade Fertilizers', 'Phosphate Grade Fertilizers', 'Seerin- (AKP) 00:60:20 is a fully water soluble fertilizer.it can be use for both i.e. for fertigation & foliar spray as it is supplies at crop growth stages, when nitrogen is not required.', '[["matter insoluble in water by weight , Maximum","0.50"],["Water soluble phosphate as P2O5 % by weight , Minimum","60.00"],["Water soluble Potash as K2O % by weight , Minimum","20.00"],["Sodium as NaCl by weight on dry basis, Maximum","0.50"],["Moisture by weight, Maximum","0.50"]]'::jsonb, 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/1580710802WhatsApp_Image_2019-12-20_at_12-removebg-preview-(1).png', 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/164404433706020-New.pdf', 'https://www.akshatfertilizer.com/products-view.php?category=1&products=7&productsId=8', '3105', 5, 'BAG', 80),
  ('AF-1-7-9', 'Seerin-14:65:00', 'Green House Grade Fertilizers', 'Phosphate Grade Fertilizers', 'Ammonium polyphosphate -APP is a polyphosphate containing N and P . its general farmula is (NH4) + 2PnO3n+1 its is gradually hydrolyzed in to H2PO4 improve P efficiency avoid P losss', '[]'::jsonb, 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/1580710836146500.png', 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/164404438146500-New.pdf', 'https://www.akshatfertilizer.com/products-view.php?category=1&products=7&productsId=9', '3105', 5, 'BAG', 90),
  ('AF-1-7-10', 'Seerin-17:44:00', 'Green House Grade Fertilizers', 'Phosphate Grade Fertilizers', 'Seerin- Urea Phosphate(17:44:00) used as an effective fertilizer for application through drip irrigation systems in field soil. While ammonia volatilization from urea fertilizer reduces N fertilizer efficiency by crops, UP releases ammonia slowly due to that the chemical bonds clench the N content. It is characteristic pH controller for improving the condition of calcareous soil white fertilization because of the low pH.', '[]'::jsonb, 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/1580710864174400.png', 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/164404446574400-New.pdf', 'https://www.akshatfertilizer.com/products-view.php?category=1&products=7&productsId=10', '3105', 5, 'BAG', 100),
  ('AF-1-8-11', 'Seerin-13:00:45', 'Green House Grade Fertilizers', 'Nitrate Grade Fertilizers (Seerin-Nitra)', 'Seein- (13:00:45) is a fully water soluble fertilizer, a high efficient source of, potassium Nitrate for plants. Potassium nitrate (KNO3) is a soluble source of two major essential plant nutrients. It’s commonly used as a fertilizer for high-value crops that benefit from nitrate (NO3-) nutrition and a source of potassium (K+) minimal amount of chloride (Cl-). Growers value fertilizing with KNO3 especially in conditions where a highly soluble, low chloride nutrient source is needed. In such soils, all of the N is immediately available for plant uptake as nitrate, requiring no additional microbial action and soil transformation.', '[]'::jsonb, 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/1580710909130045.png', 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/16440445093045-New.pdf', 'https://www.akshatfertilizer.com/products-view.php?category=1&products=8&productsId=11', '3105', 5, 'BAG', 110),
  ('AF-1-8-12', 'Seerin-CaNO3', 'Green House Grade Fertilizers', 'Nitrate Grade Fertilizers (Seerin-Nitra)', 'Seein- Calcium nitrate is a fully water soluble fertilizer, a high efficient source of Calcium and Nitrate. for plants Calcium is a “quality nutrient” that enhances yield quality and prolongs shelf life. As the mobility of calcium in the plant is limited, it has to be supplied throughout the growth season to keep adequate levels in the plant tissues and to ensure proper development. Serin-calcium nitrate is products contain nitrogen in the form of nitrate (NO3-), which enriches plant nutrition and improves the efficiency of calcium uptake.', '[]'::jsonb, 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/1580711045canitrate.png', 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/1644044549a-Nitrate-New.pdf', 'https://www.akshatfertilizer.com/products-view.php?category=1&products=8&productsId=12', '3105', 5, 'BAG', 120),
  ('AF-1-8-18', 'Seerin-Magnesium Nitrate', 'Green House Grade Fertilizers', 'Nitrate Grade Fertilizers (Seerin-Nitra)', 'Benefits : 100 % Water Soluble chloride free fertilizer. Help in crop development throught foliar spray and fertigation. benefit in nutrient ( N & Mg) deficient crop. Magnesium nitrate can use in acidic soil for better result. Basically its use in good at the harvesting stages.

FCO Specification Percent by weight

Recommendation : Recommendation are as per trials. However, Dosage and application will depend on soil analysis and crop growth satges.

Caution : Best time of spray is early morning or during evening hour when temperature is low. Do not spray during drough or water stress or diseased condition.', '[["Nitrate Nitrogen ( as NO3) ( on dry basis ) Maximum","48 %"],["Magnesium Oxide (as MgO ) Maximum","10.5 %"],["Moisture, Minimum","1.5 %"]]'::jsonb, 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/159265533813.jpg', 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/1644044428g-Nitrate-New.pdf', 'https://www.akshatfertilizer.com/products-view.php?category=1&products=8&productsId=18', '3105', 5, 'BAG', 130),
  ('AF-1-9-14', 'Seerin-00:00:50', 'Green House Grade Fertilizers', 'Sulphate Grade Fertilizers', 'Seerin- SOP (00:00:50) is a Potassium Sulphate fertilizer for Sulpha™ of all crops . It combines potassium and sulphur, two nutrients essential for plant growth. Seerin-SOP (00:00:50) is a recommended source of potassium where soil pH needs to be lowered, when sulphur is required, or when N application rates should be limited (e.g. at the end of the season).Providing concentrated nutrition, readily available for plant uptake. It enhances plant’s resistance to drought, frost, insects and diseases, thus improving yield and quality. Seerin- SOP (00:00:50) helps gaining higher nutritional value of crops, better taste and appearance, and improved suitability for transport and storage. Seerin- SOP (00:00:50) is a crystalline product, fast dissolving, highly soluble and virtually free of chloride.', '[]'::jsonb, 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/1580710085000050.png', 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/164404466800050-New.pdf', 'https://www.akshatfertilizer.com/products-view.php?category=1&products=9&productsId=14', '3105', 5, 'BAG', 140),
  ('AF-1-9-15', 'Seerin-Ammonium Sulphate', 'Green House Grade Fertilizers', 'Sulphate Grade Fertilizers', 'Seerin-Ammonium Sulphate is a CAPROLACTIUM GRADE its increasing drought tolerance through enhancing root development. helping to maintain a dark green color by promoting chlorophyll production,promoting nodule formation on legumes', '[["Specification","grade"],["Moisture % by weight , Maximum","1.00"],["Ammonical nitrogen % by weight,Minimum","20.5"],["Free Acidity as (H2SO4) % by weight, Maximum","0.025"],["Material obtained from by product ammonia and product gypsum","0.04"],["Sulphur as (S) & weight, Minimum","23.00"]]'::jsonb, 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/1580710195ammsul.png', 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/1644044702mm-sulphate-New.pdf', 'https://www.akshatfertilizer.com/products-view.php?category=1&products=9&productsId=15', '3105', 5, 'BAG', 150),
  ('AF-1-9-16', 'Seerin-Magnesium Sulphate', 'Green House Grade Fertilizers', 'Sulphate Grade Fertilizers', 'Seerin-Magnesium Sulphate is a fully water soluble fertilizer, a high efficient source of Magnesium and sulphate for plants. As a nitrogen free fertilizer, Seerin- Magnesium Sulphate is the preferred source of Magnesium and Sulphate as a crystal form .when nitrogen fertilization should be limited. is a combination of magnesium and sulphur, both nutrients beneficial for plant health. Magnesium is involved in photosynthesis, so deficiency of this nutrient affects leaf colour. Sulphur activates plant enzyme systems. A deficiency of sulphur results in growth and colour changes', '[["Specification","Grade"],["Magnesium ( Mg) % Minimum","9.5"],["Sulphur (S) % Minimum","12"],["pH ( 5% Solution )","5.0 - 8.0"]]'::jsonb, 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/1580710283magsul.png', 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/1644044742g-Sulphate.pdf', 'https://www.akshatfertilizer.com/products-view.php?category=1&products=9&productsId=16', '3105', 5, 'BAG', 160),
  ('AF-1-9-17', 'Seerin-22:18:20 ( Potasium Magnesium Sulphate)', 'Green House Grade Fertilizers', 'Sulphate Grade Fertilizers', 'Seein-potassium Magnesium Sulphate (Ultisole). is a fully water soluble fertilizer, a high efficient source of Potassium ,Magnesium, and Sulphate for plants. As a nitrogen free fertilizer, Seerin- Ultisole is Used to increased Fruit growth, and Promotes root growth, ultisole maintains chlorophyll contains of the cell .its increase the photosynthesis activity of the plants', '[]'::jsonb, 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/1580710373kms.png', 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/1644044794olysulphate-New.pdf', 'https://www.akshatfertilizer.com/products-view.php?category=1&products=9&productsId=17', '3105', 5, 'BAG', 170),
  ('AF-1-9-19', 'Potassium Schoenite', 'Green House Grade Fertilizers', 'Sulphate Grade Fertilizers', 'Potassium Schoenite', '[]'::jsonb, 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/1644043909WhatsApp-Image-2022-02-03-at-4.13.43-PM.jpeg', 'https://www.akshatfertilizer.com/uploads/green_house_grade_fertilizers/1650535059otassium-Scheonite.pdf', 'https://www.akshatfertilizer.com/products-view.php?category=1&products=9&productsId=19', '3105', 5, 'BAG', 180),
  ('AF-28-30-2', 'N:P:K:CaO +TE ( 07:00:38:11+TE)', 'Special Premium Products', 'Berry Development Special Fertilizer', 'Seerin multi-N (07:00:38:11+TE) is a 100% water-soluble fertilizer. Prepared by high-quality essential Nutrients and minimum value of Chloride. It provides maximum uptake of nutrients in crops resulting in high yield. Note: Use of this Grade fertilizers is more helpful to produce a quality of yield. Dose: According to crops duration kindly contact with our representative (Agronomist)', '[["Total Nitrogen % by weight","Minimum","07.00"],["Moisture % by weight","Maximum","0.50"],["Sodium as NaCl % by weight on a dry basis","Maximum","0.50"],["Matter Insoluble in water % by weight","Maximum","0.50"],["Water-soluble Potash (as K2O) % by weight","Minimum","38.00"],["Water-soluble Calcium (CaO) Minimum % by weight","Minimum","11.00"],["Zinc","(EDTA) Zn","150 mg/kg"],["Iron","(EDTA) Fe","120 mg/kg"],["Manganese","(EDTA) Mn","75 mg/kg"],["Copper","(EDTA) Cu","45 mg/kg"],["Boron","B","15 mg/kg"],["Molybdenum","Mo","3 mg/kg"],["Concentration %","5% (Solution)"],["EC (mS/cm)","44.59"],["pH","7.6"]]'::jsonb, 'https://www.akshatfertilizer.com/uploads/new_product/1638532421070038-2-removebg-preview.png', 'https://www.akshatfertilizer.com/uploads/new_product/1644047042038-New.pdf', 'https://www.akshatfertilizer.com/products-view.php?category=28&products=30&productsId=2', '3105', 5, 'BAG', 190),
  ('AF-28-31-4', 'N:P:K:CaO:MgO:S + TE (11:05:43:0:0:5 + TE)', 'Special Premium Products', 'Pomegranate & Banana Special Fertilizer', 'Seerin multi-N 11:05:43:05 + TE is a 100% water-soluble fertilizer. Prepared by high-quality essential Nutrients and minimum value of Chloride. It provides maximum uptake of nutrients in crops resulting in high yield. Note: Also recommended for Papaya and Onion crops. Dose: According to Crop Duration. Kindly contact our company Agronomist.', '[["Total Nitrogen % by weight","Minimum","11.00"],["Moisture % by weight","Maximum","0.50"],["Sodium as NaCl % by weight on a dry basis","Maximum","0.50"],["Matter Insoluble in water % by weight","Maximum","0.50"],["Water-soluble Phosphate (as P2O5 ) % by weight","Minimum","5.00"],["Water-soluble Potash (as K2O) Minimum % by weight","Minimum","43.00"],["Water-soluble Sulphur (S) % by weight","Minimum","5.00"],["Zinc","(EDTA) Zn","10 mg/kg"],["Iron","(EDTA) Fe","8 mg/kg"],["Manganese","(EDTA) Mn","5 mg/kg"],["Copper","(EDTA) Cu","3 mg/kg"],["Boron","B","1 mg/kg"],["Molybdenum","Mo","0.2 mg/kg"],["Concentration %","5% (Solution)"],["EC (mS/cm)","67.7"],["pH","5.7"]]'::jsonb, 'https://www.akshatfertilizer.com/uploads/new_product/163852543411543-2-removebg-preview-(2).png', 'https://www.akshatfertilizer.com/uploads/new_product/1644047957omo-Special-New_compressed.pdf', 'https://www.akshatfertilizer.com/products-view.php?category=28&products=31&productsId=4', '3105', 5, 'BAG', 200),
  ('AF-28-32-5', 'N:P:K:CaO:S +TE ( 07:36:17:02:7+TE)', 'Special Premium Products', 'Flowering & Berry Setting Crop Special', 'Seerin multi-N N:P:K:CaO:S +TE ( 07:36:17:02:7+TE) is 100% water-soluble fertilizer. Prepared by high-quality essential nutrients and minimum value of high-quality phosphorus. It provides maximum uptake of nutrients in crops resulting in high yield results. Dose: According to crop duration. Kindly contact our representative (Agronomist).', '[["Total Nitrogen % by weight","Minimum","07.00"],["Moisture % by weight","Maximum","0.50"],["Sodium as NaCl % by weight on a dry basis","Maximum","0.50"],["Matter Insoluble in water % by weight","Maximum","0.50"],["Water-soluble Phosphate (as P2O5) % by weight","Minimum","35.00"],["Water-soluble Potash (as K2O) % by weight","Minimum","17.00"],["Water-soluble Calcium (CaO) Minimum % by weight","Minimum","02.00"],["Water-soluble Sulphur (S) Minimum % by weight","Minimum","07.00"],["Zinc","(EDTA) Zn","250 mg/kg"],["Iron","(EDTA) Fe","120 mg/kg"],["Manganese","(EDTA) Mn","75 mg/kg"],["Copper","(EDTA) Cu","45 mg/kg"],["Boron","B","15 mg/kg"],["Molybdenum","Mo","3 mg/kg"],["Concentration %","5% (Solution)"],["EC (mS/cm)","49.2"],["pH","7.8"]]'::jsonb, 'https://www.akshatfertilizer.com/uploads/new_product/163853682173517-2-removebg-preview.png', 'https://www.akshatfertilizer.com/uploads/new_product/16440472813617-New.pdf', 'https://www.akshatfertilizer.com/products-view.php?category=28&products=32&productsId=5', '3105', 5, 'BAG', 210),
